type State='todo'|'done'; function label(s:State):string { switch(s){
case 'todo':return '未完';case 'done':return '完了';
default:const neverValue:never=s;return neverValue;} }

interface Greet{greet():string} class Base{greet(){return 'Hello'}}
class User extends Base implements Greet{override greet(){
return super.greet()+'!'}}
